package com.mytransitgps.modules.ciq.scheduler;
import com.mytransitgps.modules.ciq.collector.CiqRoadOpeningsCollector;import com.mytransitgps.platform.collection.*;import java.time.Instant;import java.util.concurrent.atomic.AtomicBoolean;import org.slf4j.*;import org.springframework.beans.factory.ObjectProvider;import org.springframework.scheduling.annotation.Scheduled;
/** API08 独立 Scheduler，原子锁防重入。 */
public class CiqApi08Scheduler {private static final Logger log=LoggerFactory.getLogger(CiqApi08Scheduler.class);private final CollectionExecutor executor;private final ObjectProvider<CiqRoadOpeningsCollector> provider;private final AtomicBoolean running=new AtomicBoolean();public CiqApi08Scheduler(CollectionExecutor e,ObjectProvider<CiqRoadOpeningsCollector> p){executor=e;provider=p;}@Scheduled(cron="${traffic.ciq.collectors.road-openings.cron}",zone="${traffic.ciq.timezone:Asia/Kuala_Lumpur}") public void run(){if(!running.compareAndSet(false,true)){log.warn("CIQ API08 [S-N00] 上轮未结束，本轮跳过");return;}try{var c=provider.getIfAvailable();if(c==null){log.warn("CIQ API08 [S-N01] Collector未启用，本轮跳过");return;}Instant t=Instant.now();log.info("CIQ API08 [S-N02] 定时触发，scheduledTime={}",t);executor.execute(c,CollectionContext.scheduled(ModuleCode.CIQ,CollectorCode.CIQ_ROAD_OPENINGS,t));}finally{running.set(false);}}}
